sys_script_include.script:
var ClearComment = Class.create();
ClearComment.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    clearCommentField: function() {

        var assignto = this.getParameter('sysparm_assign_to');
        //gs.info('assignto: ');
        // gs.info(assignto);

        var rs = new GlideRecord('x_1757398_reques_0_pc_request');
        rs.addQuery('assign_to', assignto);
        rs.query();
        if (rs.next()) {
            //gs.info(rs.getValue('comment'));
            rs.setValue('comment', '');
            rs.update();
            return 'OK';
        }
        return 'NG';
    },

    type: 'ClearComment'
});
